// fayl: app/ClientRecipes.tsx
"use client"
import { useEffect, useState } from "react"

// Oddiy React (SPA) usuli: sahifa bo'sh keladi, ma'lumot brauzerda olinadi
export default function ClientRecipes() {
  const [recipes, setRecipes] = useState<{ id: number; title: string }[] | null>(null)
  useEffect(() => {
    fetch("/api/recipes").then((r) => r.json()).then(setRecipes)
  }, [])
  return (
    <section>
      <h2>Brauzerda (SPA)</h2>
      {recipes ? <ul>{recipes.map((r) => <li key={r.id}>{r.title}</li>)}</ul> : <p>Yuklanmoqda...</p>}
    </section>
  )
}

