// fayl: app/page.tsx
// terminalda: npm install zod
import { z } from "zod"

const Order = z.object({
  dish: z.string().min(2),
  count: z.number().int().positive(),
})

export default function Home() {
  const ok = Order.safeParse({ dish: "osh", count: 2 })
  const bad = Order.safeParse({ dish: "o", count: -1 })
  return (
    <ul>
      <li>To'g'ri buyurtma: {String(ok.success)}</li>
      <li>Xato maydonlar: {bad.error?.issues.map((i) => i.path.join(".")).join(", ")}</li>
    </ul>
  )
}

